UPDATE Language_ko_KR
SET Text = 'Completing a [ICON_CARAVAN] Land Trade Route originating here and targeting another Civilization, triggers a (or strengthens an existing) [COLOR_POSITIVE_TEXT]Historic Event[ENDCOLOR].[NEWLINE][NEWLINE]+1 [ICON_FOOD] Food and [ICON_GOLD] Gold for every 2 Desert or 2 Tundra tiles worked by the City, and for every Marsh. [ICON_CARAVAN] Land Trade Routes gain +50% Range and +3 [ICON_GOLD] Gold.[NEWLINE][NEWLINE]Nearby [ICON_RES_TRUFFLES] Truffles: +2 [ICON_GOLD] Gold.[NEWLINE]Nearby [ICON_RES_COTTON] Cotton: +1 [ICON_PRODUCTION] Production, +1 [ICON_CULTURE] Culture.[NEWLINE]Nearby [ICON_RES_FUR] Furs: +1 [ICON_GOLD] Gold, +1 [ICON_PRODUCTION] Production.'
WHERE Tag = 'TXT_KEY_BUILDING_CARAVANSARY_HELP';

UPDATE Language_ko_KR
SET Text = 'When a [ICON_INTERNATIONAL_TRADE] Land Trade Route originating here and targeting another Civ is completed, receive a [ICON_TOURISM] Tourism boost with the Civ based on recent [ICON_CULTURE] Culture and [ICON_TOURISM] Tourism output. +1 [ICON_FOOD] Food and [ICON_GOLD] Gold for every 2 Desert or Tundra tiles worked by the City, and for every Marsh.[NEWLINE][NEWLINE][ICON_INTERNATIONAL_TRADE] Land Trade Routes gain +75% Range and +3 [ICON_GOLD] Gold. Incoming [ICON_INTERNATIONAL_TRADE] Trade Routes generate +2 [ICON_GOLD] Gold for the City and the Trade Route Owner. +2 [ICON_GOLD] Gold, [ICON_PRODUCTION] Production, and [ICON_CULTURE] Culture if a [ICON_INTERNATIONAL_TRADE] Trade Unit passes through the City.[NEWLINE]Nearby [ICON_RES_TRUFFLES] Truffles: +2 [ICON_GOLD] Gold.[NEWLINE]Nearby [ICON_RES_COTTON] Cotton: +1 [ICON_PRODUCTION] Production, +1 [ICON_CULTURE] Culture.[NEWLINE]Nearby [ICON_RES_FUR] Furs: +1 [ICON_GOLD] Gold, +1 [ICON_PRODUCTION] Production.[NEWLINE]+1 [ICON_GOLD] Gold to all Nearby Luxuries.'
WHERE Tag = 'TXT_KEY_BUILDING_SONGHAI_GUMEY_HELP';

